{
  "archislopVersion": 1,
  "theme": "whiteboard",
  "spec": {
    "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
    "title": "Where my monthly budget goes",
    "description": "Monthly budget allocation across rent, food, transport, fun and savings, in dollars.",
    "data": {
      "values": [
        { "category": "Rent", "amount": 1450 },
        { "category": "Food", "amount": 520 },
        { "category": "Transport", "amount": 210 },
        { "category": "Fun", "amount": 280 },
        { "category": "Savings", "amount": 540 }
      ]
    },
    "transform": [
      { "calculate": "datum.amount / 3000", "as": "share" }
    ],
    "encoding": {
      "y": {
        "field": "category",
        "type": "nominal",
        "sort": "-x",
        "axis": { "title": null }
      }
    },
    "layer": [
      {
        "mark": { "type": "bar", "cornerRadiusEnd": 4 },
        "encoding": {
          "x": {
            "field": "amount",
            "type": "quantitative",
            "axis": { "title": "Monthly spend (USD)", "format": "$,.0f" }
          },
          "color": {
            "field": "category",
            "type": "nominal",
            "legend": null,
            "scale": { "scheme": "tableau10" }
          }
        }
      },
      {
        "mark": {
          "type": "text",
          "align": "left",
          "dx": 6,
          "fontSize": 11
        },
        "encoding": {
          "x": { "field": "amount", "type": "quantitative" },
          "text": {
            "field": "share",
            "type": "quantitative",
            "format": ".0%"
          }
        }
      }
    ]
  }
}

